const request = $input.first().json;
const headers = $input.first().headers;

// Extract API key
const apiKey = headers['x-api-key'] || headers['authorization']?.replace('Bearer ', '');

if (!apiKey) {
  throw new Error('API key required');
}

// Extract model ID from URL parameters
const modelId = $input.first().params.model_id;

if (!modelId) {
  throw new Error('Model ID required');
}

return {
  api_key: apiKey,
  model_id: modelId,
  input_data: request,
  timestamp: new Date().toISOString()
};

const accessData = $input.first().json;

if (!accessData || accessData.length === 0) {
  throw new Error('No access to this model or invalid API key');
}

const modelData = accessData[0];

// Check if user has remaining API calls
if (modelData.api_calls_remaining <= 0) {
  throw new Error('API call limit exceeded. Please upgrade your plan.');
}

// Check model availability
if (modelData.status !== 'active') {
  throw new Error('Model is currently unavailable');
}

return {
  user_id: modelData.user_id,
  model_id: modelData.model_id,
  model_url: modelData.model_url,
  model_type: modelData.model_type,
  price_per_call: modelData.price_per_call || 0.05,
  input_data: $node['Validate API Access'].json.input_data,
  api_calls_remaining: modelData.api_calls_remaining
};

const replicateResponse = $node['Call Replicate Model'].json;
const usageData = $node['Validate Usage Limits'].json;

return {
  success: true,
  model_id: usageData.model_id,
  prediction_id: replicateResponse.id,
  status: replicateResponse.status,
  output: replicateResponse.output,
  created_at: replicateResponse.created_at,
  completed_at: replicateResponse.completed_at,
  cost: usageData.price_per_call,
  remaining_calls: usageData.api_calls_remaining - 1,
  processing_time: replicateResponse.metrics?.predict_time
};

const request = $input.first().json;
const headers = $input.first().headers;

// Validate batch size
if (!request.batch_inputs || !Array.isArray(request.batch_inputs)) {
  throw new Error('batch_inputs array is required');
}

if (request.batch_inputs.length > 50) {
  throw new Error('Maximum 50 predictions per batch');
}

if (request.batch_inputs.length === 0) {
  throw new Error('At least 1 prediction required');
}

const apiKey = headers['x-api-key'] || headers['authorization']?.replace('Bearer ', '');
const modelId = $input.first().params.model_id;

return {
  api_key: apiKey,
  model_id: modelId,
  batch_inputs: request.batch_inputs,
  batch_size: request.batch_inputs.length,
  callback_url: request.callback_url,
  timestamp: new Date().toISOString()
};

const batchData = $input.first().json;
const predictions = [];

// Create individual prediction requests
for (let i = 0; i < batchData.batch_inputs.length; i++) {
  predictions.push({
    batch_id: `batch_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
    prediction_index: i,
    input_data: batchData.batch_inputs[i],
    model_id: batchData.model_id,
    api_key: batchData.api_key,
    callback_url: batchData.callback_url
  });
}

return predictions;

const analyticsData = $input.first().json;

// Group by date and calculate totals
const dailyRevenue = {};
let totalRevenue = 0;
let totalCalls = 0;

analyticsData.forEach(row => {
  const date = row.date.split('T')[0];

  if (!dailyRevenue[date]) {
    dailyRevenue[date] = {
      date: date,
      revenue: 0,
      calls: 0,
      models: {}
    };
  }

  dailyRevenue[date].revenue += parseFloat(row.total_revenue);
  dailyRevenue[date].calls += parseInt(row.total_calls);
  dailyRevenue[date].models[row.model_id] = {
    revenue: parseFloat(row.total_revenue),
    calls: parseInt(row.total_calls),
    avg_cost: parseFloat(row.avg_cost_per_call)
  };

  totalRevenue += parseFloat(row.total_revenue);
  totalCalls += parseInt(row.total_calls);
});

return {
  summary: {
    total_revenue_30d: totalRevenue,
    total_calls_30d: totalCalls,
    avg_revenue_per_call: totalRevenue / totalCalls,
    avg_calls_per_day: totalCalls / 30
  },
  daily_breakdown: Object.values(dailyRevenue),
  period: '30_days',
  generated_at: new Date().toISOString()
};
